#include <zephyr/kernel.h>
#include <zephyr/audio/dmic.h>
#include <zephyr/sys/printk.h>
#include <string.h>

#define RATE          16000
#define BLOCK_SAMPLES (RATE / 10)          /* 100 ms = 1600 samples */
#define BLOCK_BYTES   (BLOCK_SAMPLES * 2)  /* 16-bit = 3200 bytes   */
#define SECONDS       5
#define TOTAL_SAMPLES (RATE * SECONDS)     /* 80000 samples         */

K_MEM_SLAB_DEFINE_STATIC(mem_slab, BLOCK_BYTES, 4, 4);
static int16_t recording[TOTAL_SAMPLES];   /* 160 KB of RAM */

int main(void)
{
	const struct device *dmic = DEVICE_DT_GET(DT_NODELABEL(dmic_dev));

	k_sleep(K_SECONDS(5));
	if (!device_is_ready(dmic)) {
		printk("mic not ready\n");
		return 0;
	}

	struct pcm_stream_cfg stream = {
		.pcm_rate = RATE,
		.pcm_width = 16,
		.block_size = BLOCK_BYTES,
		.mem_slab = &mem_slab,
	};
	struct dmic_cfg cfg = {
		.io = {
			.min_pdm_clk_freq = 1000000,
			.max_pdm_clk_freq = 3500000,
			.min_pdm_clk_dc = 40,
			.max_pdm_clk_dc = 60,
		},
		.streams = &stream,
		.channel = {
			.req_num_streams = 1,
			.req_num_chan = 1,
			.req_chan_map_lo = dmic_build_channel_map(0, 0, PDM_CHAN_LEFT),
		},
	};

	if (dmic_configure(dmic, &cfg) < 0) {
		printk("configure failed\n");
		return 0;
	}

	printk("Recording 5 s... talk now\n");
	dmic_trigger(dmic, DMIC_TRIGGER_START);

	size_t n = 0;
	while (n < TOTAL_SAMPLES) {
		void *buf;
		uint32_t size;

		if (dmic_read(dmic, 0, &buf, &size, 1000) < 0) {
			printk("read failed\n");
			return 0;
		}
		size_t count = MIN(size / 2, TOTAL_SAMPLES - n);
		memcpy(&recording[n], buf, count * 2);
		n += count;
		k_mem_slab_free(&mem_slab, buf);
	}
	dmic_trigger(dmic, DMIC_TRIGGER_STOP);

	printk("BEGIN\n");
	for (size_t i = 0; i < TOTAL_SAMPLES; i += 16) {
		for (size_t j = 0; j < 16; j++) {
			printk("%04x", (uint16_t)recording[i + j]);
		}
		printk("\n");
	}
	printk("END\n");
	return 0;
}
